def topKFrequent(nums, k):
    count = Counter(nums)
    heap = []
    for num, freq in count.items():
        heapq.heappush(heap, (freq, num))
        if len(heap) > k:
            heapq.heappop(heap)
    return [num for freq, num in heap]

def numIslands(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] != '1':
            return
        grid[r][c] = '0'
        dfs(r+1, c)
        dfs(r-1, c)
        dfs(r, c+1)
        dfs(r, c-1)
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '1':
                count += 1
                dfs(r, c)
    return count

def canFinish(numCourses, prerequisites):
    from collections import defaultdict
    adj = defaultdict(list)
    for dest, src in prerequisites:
        adj[src].append(dest)
    state = [0] * numCourses  # 0=unvisited, 1=visiting, 2=visited
    def has_cycle(v):
        if state[v] == 1:
            return True
        if state[v] == 2:
            return False
        state[v] = 1
        for nei in adj[v]:
            if has_cycle(nei):
                return True
        state[v] = 2
        return False
    for i in range(numCourses):
        if has_cycle(i):
            return False
    return True

import heapq

def find_kth_largest(nums, k):
    heap = nums[:k]
    heapq.heapify(heap)
    for num in nums[k:]:
        if num > heap[0]:
            heapq.heappushpop(heap, num)
    return heap[0]

import heapq

def merge_k_sorted_lists(lists):
    heap = []
    for i, lst in enumerate(lists):
        if lst:
            heapq.heappush(heap, (lst[0], i, 0))
    result = []
    while heap:
        val, list_idx, elem_idx = heapq.heappop(heap)
        result.append(val)
        if elem_idx + 1 < len(lists[list_idx]):
            next_tuple = (lists[list_idx][elem_idx + 1], list_idx, elem_idx + 1)
            heapq.heappush(heap, next_tuple)
    return result

from collections import deque

def ladderLength(beginWord, endWord, wordList):
    word_set = set(wordList)
    if endWord not in word_set:
        return 0
    queue = deque([(beginWord, 1)])
    visited = set([beginWord])
    while queue:
        word, steps = queue.popleft()
        if word == endWord:
            return steps
        for i in range(len(word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                next_word = word[:i] + c + word[i+1:]
                if next_word in word_set and next_word not in visited:
                    visited.add(next_word)
                    queue.append((next_word, steps + 1))
    return 0

def coinChange(coins, amount):
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for coin in coins:
            if coin <= a:
                dp[a] = min(dp[a], dp[a - coin] + 1)
    return dp[amount] if dp[amount] <= amount else -1

def search(nums, target):
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        # Left half is sorted
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # Right half is sorted
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1
    return -1

def group_anagrams(words):
    groups = {}
    for word in words:
        key = ''.join(sorted(word))
        if key not in groups:
            groups[key] = []
        groups[key].append(word)
    return list(groups.values())

from collections import deque

def levelOrder(root):
    if not root:
        return []
    result = []
    queue = deque([root])
    while queue:
        level = []
        for _ in range(len(queue)):
            node = queue.popleft()
            level.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        result.append(level)
    return result

def isValidBST(root):
    def helper(node, low, high):
        if not node:
            return True
        if not (low < node.val < high):
            return False
        return (helper(node.left, low, node.val) and
                helper(node.right, node.val, high))
    return helper(root, float('-inf'), float('inf'))

def trap(height):
    n = len(height)
    if n < 3:
        return 0
    left_max = [0] * n
    right_max = [0] * n
    left_max[0] = height[0]
    for i in range(1, n):
        left_max[i] = max(left_max[i-1], height[i])
    right_max[-1] = height[-1]
    for i in range(n-2, -1, -1):
        right_max[i] = max(right_max[i+1], height[i])
    trapped = 0
    for i in range(n):
        trapped += max(0, min(left_max[i], right_max[i]) - height[i])
    return trapped

from collections import defaultdict
from datetime import datetime

# Assume log lines are in the format: '[YYYY-MM-DD HH:MM:SS] ERROR_TYPE: message'
def top_error_per_hour(log_file_path):
    error_counts = defaultdict(lambda: defaultdict(int))  # {hour: {error_type: count}}
    with open(log_file_path) as f:
        for line in f:
            if not line.strip():
                continue
            try:
                timestamp_str = line[1:20]  # '[YYYY-MM-DD HH:MM:SS]'
                hour = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S').replace(minute=0, second=0)
                rest = line[22:].strip()
                error_type = rest.split(':', 1)[0]
                error_counts[hour][error_type] += 1
            except Exception:
                continue  # skip malformed lines
    result = {}
    for hour, errors in error_counts.items():
        top_error = max(errors.items(), key=lambda x: x[1])[0]
        result[hour] = top_error
    return result

import time
import threading

def debounce(fn, wait):
    timer = None
    lock = threading.Lock()

    def debounced(*args, **kwargs):
        nonlocal timer
        def call_fn():
            fn(*args, **kwargs)
        with lock:
            if timer:
                timer.cancel()
            timer = threading.Timer(wait, call_fn)
            timer.start()
    return debounced

def throttle(fn, interval):
    last_called = [0]
    lock = threading.Lock()

    def throttled(*args, **kwargs):
        now = time.time()
        with lock:
            if now - last_called[0] >= interval:
                last_called[0] = now
                fn(*args, **kwargs)
    return throttled
